protected static <V, E> GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour.isEmpty()) {
        return null;
    }

    V startVertex = null;
    for (V vertex : graph.vertexSet()) {
        if (tour.stream().anyMatch(edge -> edge.getSource().equals(vertex) || edge.getTarget().equals(vertex))) {
            startVertex = vertex;
            break;
        }
