        Set<Vertex> endNeighbors = graph.getNeighbors(end);

        startNeighbors.remove(start);
        endNeighbors.remove(end);

        startNeighbors.retainAll(endNeighbors);

        for (Vertex vertex : startNeighbors) {
            separators.add(Pair.with(vertex.getId(), vertex.getId()));
        }

        return separators;
    }
