            byte[] newBuffer = new byte[buffer.length * 2];
            System.arraycopy(buffer, 0, newBuffer, 0, offset);
            buffer = newBuffer;
        }
    }

    // Resize buffer to actual data size
    byte[] resizedBuffer = new byte[offset];
    System.arraycopy(buffer, 0, resizedBuffer, 0, offset);
    // Reset to the start of the buffer
    // (Assuming a field called 'data' holds the buffer)
    this.data = resizedBuffer;
}

