import java.util.Iterator;

public class CategoryTree {

    private static class Node {
        boolean isActive;
        List<Node> children;

        Node(boolean isActive) {
            this.isActive = isActive;
            this.children = new ArrayList<>();
        }
    }

    private Node root;

    protected int removeUnusedNodes() {
        removeInactiveNodes(root);
        return countActiveNodes();
    }

    private boolean removeInactiveNodes(Node node) {
        if (node == null) {
            return false;
        }

        Iterator<Node> it = node.children.iterator();
        while (it.hasNext()) {
            Node child = it.next();
            if (!removeInactiveNodes(child)) {
                it.remove();
            }
        }

        return node.isActive;
    }

    private int countActiveNodes() {
        return countActiveNodesRecursive(root);
    }

    private int countActiveNodesRecursive(Node node) {
        if (node == null) {
            return 0;
        }

        int count = node.isActive ? 1 : 0;
        for (Node child : node.children) {
            count += countActiveNodesRecursive(child);
        }

        return count;
    }
}

