public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 1) {
        return 2;
    }
    int prime = desiredCapacity;
    boolean found = false;
    while (!found) {
        if (isPrime(prime)) {
            found = true;
        } else {
            prime++;
        }
        if (desiredCapacity >= 1000) {
            if ((double) (prime - desiredCapacity) / desiredCapacity > 0.11) {
                prime = desiredCapacity;
                desiredCapacity += 11 * desiredCapacity / 100;
            }
        }
    }
    return prime;
}

